pub struct SceneRasterGpuWitness {
    inner: Arc<SceneRasterPoolInner>,
    slot: u16,
    epoch: u64,
    identity: SceneRasterIdentity,
}

impl fmt::Debug for SceneRasterReleaseWitness {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
