        }
        *self.0.frame_inputs.lock().expect("runtime frame inputs lock") = frame_job::FrameBuildInputs { wheel_zoom_deadline_ms: runtime.wheel_zoom_deadline_ms, now_ms: app_now_ms() };
    }

