            let end = (view.byte_offset as usize).checked_add(view.byte_length as usize).ok_or("GLB bufferView BIN span overflowed")?;
            if end > self.bin_bytes {
                return Err("GLB bufferView exceeded the BIN payload");
            }
        }
        for image in self.schema.images[..usize::from(self.schema.image_len)].iter().flatten() {
            let view = self.schema.views.get(usize::from(image.view.ok_or("GLB image lost its embedded bufferView")?)).and_then(Option::as_ref).ok_or("GLB image referenced a missing bufferView")?;
            let end = (view.byte_offset as usize).checked_add(view.byte_length as usize).ok_or("GLB image bufferView BIN span overflowed")?;
            if end > self.bin_bytes {
                return Err("GLB image bufferView exceeded the BIN payload");
            }
        }
        Ok(())
    }

    fn texture_key(&self, owner: &RendererAssetFetchOwner) -> String {
        format!("glb:{}:texture:{}:{}", owner.generation(), self.texture, if self.texture_role == 0 {"srgb"} else {"linear"})
    }

    fn build_appearance(&mut self, owner: &RendererAssetFetchOwner) -> Result<World3dMeshAppearance, &'static str> {
        let mut primitives = Vec::new();
        primitives.try_reserve_exact(usize::from(self.plan.instance_len)).map_err(|_| "GLB material appearance exceeded allocation credits")?;
        for instance in self.plan.instances[..usize::from(self.plan.instance_len)].iter().flatten() {
            let primitive = self.schema.primitives.get(usize::from(instance.primitive)).and_then(Option::as_ref).ok_or("GLB materializer lost a primitive material")?;
            let material = primitive
                .material
                .and_then(|index| self.schema.materials.get(usize::from(index)).and_then(Option::as_ref).copied())
                .unwrap_or_default();
            let base_color_texture = material.base_color_texture.map(|texture| format!("glb:{}:texture:{texture}:srgb", owner.generation()));
            let sampler_for = |reference:Option<u16>| -> Result<ui_wgpu::wgpu::SceneTextureSampler3d, &'static str> {Ok(if let Some(texture) = reference {
                let texture = self.schema.textures.get(usize::from(texture)).and_then(Option::as_ref).ok_or("GLB materializer lost a texture sampler owner")?;
                let sampler = texture.sampler.and_then(|index| self.schema.samplers.get(usize::from(index)).and_then(Option::as_ref).copied()).unwrap_or_default();
                ui_wgpu::wgpu::SceneTextureSampler3d {
                    wrap_u: glb_texture_wrap(sampler.wrap_s)?,
                    wrap_v: glb_texture_wrap(sampler.wrap_t)?,
                    mag_filter: glb_mag_filter(sampler.mag_filter)?,
                    min_filter: glb_min_filter(sampler.min_filter)?,
                }
            } else {
                Default::default()
            })};
            let texture_sampler = sampler_for(material.base_color_texture)?;
            let additional_texture_samplers = [sampler_for(material.additional_textures[0])?,sampler_for(material.additional_textures[1])?,sampler_for(material.additional_textures[2])?,sampler_for(material.additional_textures[3])?];
            let reference = |role:usize| material.additional_textures[role].map(|texture|format!("glb:{}:texture:{texture}:{}",owner.generation(),if role==3 {"srgb"} else {"linear"}));
            primitives.push(World3dPrimitiveMaterial {
                first_index: instance.index_base,
                index_count: instance.index_count,
                material: ui_wgpu::wgpu::SceneAuthoredMaterial3d {
                    base_color: material.base_color,
                    emissive: material.emissive,
                    metalness: material.metalness,
                    roughness: material.roughness,
                    alpha: match material.alpha_mode {
                        0 => ui_wgpu::wgpu::SceneMaterialAlpha3d::Opaque,
                        1 => ui_wgpu::wgpu::SceneMaterialAlpha3d::Mask,
                        2 => ui_wgpu::wgpu::SceneMaterialAlpha3d::Blend,
                        _ => return Err("GLB materializer reached an unsupported alpha mode"),
                    },
                    alpha_cutoff: material.alpha_cutoff,
                    double_sided: material.double_sided,
                    preserve_vertex_color: primitive.color.is_some(),
                    base_color_texture,
                    texture_sampler,
                    metallic_roughness_texture:reference(0),normal_texture:reference(1),occlusion_texture:reference(2),emissive_texture:reference(3),additional_texture_samplers,
                normal_scale:[material.normal_scale,if primitive.tangent.is_some(){material.normal_scale}else{-material.normal_scale}],occlusion_strength:material.occlusion_strength,},
            });
        }
        let textures = std::mem::take(&mut self.textures);
        World3dMeshAppearance::new(primitives, textures).map_err(|(_primitives, textures)| {
            self.textures = textures;
            "GLB material appearance exceeded fixed owner credits"
        })
    }

    fn read_vec(&self, owner: &RendererAssetFetchOwner, pages: &RendererAssetPageIndex, accessor: u16, item: u32, components: usize) -> Result<[f32; 4], &'static str> {
        let schema = self.schema.accessor(accessor)?;
        if usize::from(schema.kind) != components || item >= schema.count {
            return Err("GLB accessor semantic read exceeded its shape");
        }
        let mut result = [0.0; 4];
        for (component, output) in result[..components].iter_mut().enumerate() {
            *output = self.read_component(owner, pages, schema, item, component)?;
        }
        Ok(result)
    }

    fn read_component(&self, owner: &RendererAssetFetchOwner, pages: &RendererAssetPageIndex, accessor: &GlbAccessorSchema, item: u32, component: usize) -> Result<f32, &'static str> {
        let view = self.schema.views.get(usize::from(accessor.view)).and_then(Option::as_ref).ok_or("GLB accessor semantic read lost its bufferView")?;
        let component_bytes = glb_component_bytes(accessor.component)?;
        let item_bytes = usize::from(accessor.kind).checked_mul(component_bytes).ok_or("GLB accessor semantic item bytes overflowed")?;
        let stride = if view.byte_stride == 0 { item_bytes } else { usize::from(view.byte_stride) };
        let relative = (view.byte_offset as usize)
            .checked_add(accessor.byte_offset as usize)
            .and_then(|offset| usize::try_from(item).ok().and_then(|item| item.checked_mul(stride)).and_then(|item| offset.checked_add(item)))
            .and_then(|offset| offset.checked_add(component * component_bytes))
            .ok_or("GLB accessor semantic address overflowed")?;
        let absolute = self.bin_start.checked_add(relative).ok_or("GLB accessor absolute address overflowed")?;
        glb_read_component(owner, pages, absolute, accessor.component, accessor.normalized)
    }

    /// 🎯️ One exact `u32` sub-element id; `read_component` widens through `f32` and would corrupt ids past 2^24.
    fn read_unsigned_id(&self, owner: &RendererAssetFetchOwner, pages: &RendererAssetPageIndex, accessor: u16, item: u32) -> Result<u32, &'static str> {
        let schema = self.schema.accessor(accessor)?;
        if schema.component != 5125 || schema.kind != 1 || item >= schema.count {
            return Err("GLB sub-element id read exceeded its shape");
        }
        let view = self.schema.views.get(usize::from(schema.view)).and_then(Option::as_ref).ok_or("GLB sub-element id read lost its bufferView")?;
        let stride = if view.byte_stride == 0 { size_of::<u32>() } else { usize::from(view.byte_stride) };
        let relative = (view.byte_offset as usize)
            .checked_add(schema.byte_offset as usize)
            .and_then(|offset| usize::try_from(item).ok().and_then(|item| item.checked_mul(stride)).and_then(|item| offset.checked_add(item)))
            .ok_or("GLB sub-element id address overflowed")?;
        let absolute = self.bin_start.checked_add(relative).ok_or("GLB sub-element id absolute address overflowed")?;
        Ok(u32::from_le_bytes(pages.read::<4>(owner, absolute)?))
    }

    fn read_output_index(&self, owner: &RendererAssetFetchOwner, pages: &RendererAssetPageIndex, primitive: &GlbPrimitiveSchema, output: u32, vertex_count: u32) -> Result<u32, &'static str> {
        let triangle = output / 3;
        let component = output % 3;
        let source = match (primitive.mode, component) {
            (4, component) => triangle * 3 + component,
            (5, component) if triangle.is_multiple_of(2) => triangle + component,
            (5, 0) => triangle + 1,
            (5, 1) => triangle,
            (5, 2) => triangle + 2,
            (6, 0) => 0,
            (6, 1) => triangle + 1,
            (6, 2) => triangle + 2,
            _ => return Err("GLB materializer reached an unsupported primitive mode"),
        };
        let result = if let Some(accessor) = primitive.indices {
            let accessor = self.schema.accessor(accessor)?;
            let value = self.read_component(owner, pages, accessor, source, 0)?;
            if value < 0.0 || value > u32::MAX as f32 || value.fract() != 0.0 {
                return Err("GLB index value was not an admitted integer");
            }
            value as u32
        } else {
            source
        };
        (result < vertex_count).then_some(result).ok_or("GLB index exceeded POSITION count")
    }

    fn instance(&self) -> Result<GlbInstanceOutput, &'static str> {
        self.plan.instances.get(usize::from(self.instance)).and_then(Option::as_ref).copied().ok_or("GLB materializer lost an instance plan")
    }

    fn primitive(&self, instance: GlbInstanceOutput) -> Result<&GlbPrimitiveSchema, &'static str> {
        self.schema.primitives.get(usize::from(instance.primitive)).and_then(Option::as_ref).ok_or("GLB materializer lost a primitive schema")
    }

    fn write_token(&self) -> Result<Mesh3dWriteToken, &'static str> {
        self.write.ok_or("GLB materializer lost its mesh write claim")
    }

    fn take_asset(&mut self) -> Option<World3dMeshAsset> {
        Some(World3dMeshAsset { mesh: self.lease.take()?, appearance: self.appearance.take()? })
    }

    fn restore_asset(&mut self, asset: World3dMeshAsset) {
        assert!(self.lease.replace(asset.mesh).is_none(), "GLB publication restores exactly one retained mesh lease");
        assert!(self.appearance.replace(asset.appearance).is_none(), "GLB publication restores exactly one retained appearance owner");
    }

    fn next_instance(&mut self) {
        self.instance += 1;
        self.item = 0;
        self.normal_substep = 0;
    }

    fn advance_phase(&mut self, phase: GlbMaterializePhase) {
        self.phase = phase;
        self.instance = 0;
        self.item = 0;
        self.normal_substep = 0;
    }

    fn begin_close(&mut self) {
        self.texture_cancelled.store(true,Ordering::Release);
        self.phase = GlbMaterializePhase::Closing;
    }

    fn close_step(&mut self) -> bool {
        self.begin_close();
        if self.texture_submission.take().is_some(){self.texture_worker=None;return false}
        if let Some(worker)=self.texture_worker.as_ref(){let Ok(mut output)=worker.try_lock()else{return false};let Some(image)=output.take()else{return false};self.decoded_texture=image.map(|image|DecodedReferenceImage{width:image.width,height:image.height,pixels:image.pixels,source_digest:self.texture_digest});drop(output);self.texture_worker=None;return false}
        if let Some(mut job)=self.texture_png.take(){job.cancel();return false}
        if let Some(image)=self.decoded_texture.as_mut(){if !image.pixels.is_empty(){image.pixels.truncate(image.pixels.len().saturating_sub(4096));return false}self.decoded_texture=None;return false}
        if !self.texture_bytes.is_empty(){self.texture_bytes.truncate(self.texture_bytes.len().saturating_sub(4096));return false}
        if let Some(appearance)=self.appearance.as_mut(){if !appearance.close_step(){return false}self.appearance=None;return false}
        if self.textures.pop().is_some(){return false}
        if let Some(token) = self.write {
            match mesh3d_abort(token) {
                Ok(()) | Err(Mesh3dFault::Closing) => {}
                Err(Mesh3dFault::Stale) => {
                    self.write = None;
                    return self.lease.is_none() && self.appearance.is_none() && self.textures.is_empty();
                }
                Err(_) => return false,
            }
            match mesh3d_abort_step(token) {
                Ok(true) | Err(Mesh3dFault::Stale) => self.write = None,
                Ok(false) | Err(_) => return false,
            }
            return self.lease.is_none() && self.appearance.is_none() && self.textures.is_empty();
        }
        if let Some(lease) = self.lease {
            match mesh3d_begin_close(lease) {
                Ok(()) | Err(Mesh3dFault::Closing) => {}
                Err(Mesh3dFault::Stale) => {
                    self.lease = None;
                    return true;
                }
                Err(_) => return false,
            }
            match mesh3d_close_step(lease) {
                Ok(true) | Err(Mesh3dFault::Stale) => self.lease = None,
                Ok(false) | Err(_) => return false,
            }
        }
        true
    }
}

fn glb_texture_wrap(value: u16) -> Result<ui_wgpu::wgpu::SceneTextureWrap3d, &'static str> {
    match value {
        33071 => Ok(ui_wgpu::wgpu::SceneTextureWrap3d::ClampToEdge),
        10497 => Ok(ui_wgpu::wgpu::SceneTextureWrap3d::Repeat),
        33648 => Ok(ui_wgpu::wgpu::SceneTextureWrap3d::MirrorRepeat),
        _ => Err("GLB texture sampler used an unsupported wrap mode"),
    }
}

fn glb_mag_filter(value: Option<u16>) -> Result<ui_wgpu::wgpu::SceneTextureFilter3d, &'static str> {
    match value {
        None | Some(9729) => Ok(ui_wgpu::wgpu::SceneTextureFilter3d::Linear),
        Some(9728) => Ok(ui_wgpu::wgpu::SceneTextureFilter3d::Nearest),
        Some(_) => Err("GLB texture sampler used an unsupported magnification filter"),
    }
}

fn glb_min_filter(value: Option<u16>) -> Result<ui_wgpu::wgpu::SceneTextureFilter3d, &'static str> {
    match value {
        None => Ok(ui_wgpu::wgpu::SceneTextureFilter3d::LinearMipmapLinear),
        Some(9729) => Ok(ui_wgpu::wgpu::SceneTextureFilter3d::Linear),
        Some(9985)=>Ok(ui_wgpu::wgpu::SceneTextureFilter3d::LinearMipmapNearest),
        Some(9987)=>Ok(ui_wgpu::wgpu::SceneTextureFilter3d::LinearMipmapLinear),
        Some(9984)=>Ok(ui_wgpu::wgpu::SceneTextureFilter3d::NearestMipmapNearest),
        Some(9986)=>Ok(ui_wgpu::wgpu::SceneTextureFilter3d::NearestMipmapLinear),
        Some(9728) => Ok(ui_wgpu::wgpu::SceneTextureFilter3d::Nearest),
        Some(_) => Err("GLB texture sampler used an unsupported minification filter"),
    }
}

fn glb_mesh_fault(fault: Mesh3dFault) -> &'static str {
    match fault {
        Mesh3dFault::Closing => "GLB paged mesh authority was closing",
        Mesh3dFault::ItemCapacity => "GLB paged mesh authority exhausted fixed owner slots",
        Mesh3dFault::PageCapacity => "GLB paged mesh authority exhausted aggregate page credits",
        Mesh3dFault::ByteCapacity => "GLB paged mesh exceeded fixed byte credits",
        Mesh3dFault::Schema => "GLB paged mesh schema was invalid",
        Mesh3dFault::Stale => "GLB paged mesh generation/revision witness was stale",
        Mesh3dFault::Order => "GLB paged mesh field order was invalid",
        Mesh3dFault::Incomplete => "GLB paged mesh was not terminally complete",
    }
}

fn glb_component_bytes(component: u16) -> Result<usize, &'static str> {
    match component {
        5120 | 5121 => Ok(1),
        5122 | 5123 => Ok(2),
        5125 | 5126 => Ok(4),
        _ => Err("GLB component type was unsupported"),
    }
}

fn glb_read_component(owner: &RendererAssetFetchOwner, pages: &RendererAssetPageIndex, absolute: usize, component: u16, normalized: bool) -> Result<f32, &'static str> {
    let value = match component {
        5120 => {
            let value = i8::from_le_bytes(pages.read::<1>(owner, absolute)?);
            if normalized {
                (f32::from(value) / 127.0).max(-1.0)
            } else {
                f32::from(value)
            }
        }
        5121 => {
            let value = u8::from_le_bytes(pages.read::<1>(owner, absolute)?);
            if normalized {
                f32::from(value) / 255.0
            } else {
                f32::from(value)
            }
        }
        5122 => {
            let value = i16::from_le_bytes(pages.read::<2>(owner, absolute)?);
            if normalized {
                (f32::from(value) / 32767.0).max(-1.0)
            } else {
                f32::from(value)
            }
        }
        5123 => {
            let value = u16::from_le_bytes(pages.read::<2>(owner, absolute)?);
            if normalized {
                f32::from(value) / 65535.0
            } else {
                f32::from(value)
            }
        }
        5125 => {
            let value = u32::from_le_bytes(pages.read::<4>(owner, absolute)?);
            if normalized {
                value as f32 / u32::MAX as f32
            } else {
                value as f32
            }
        }
        5126 if !normalized => f32::from_le_bytes(pages.read::<4>(owner, absolute)?),
        5126 => return Err("GLB FLOAT accessor could not be normalized"),
        _ => return Err("GLB semantic component type was unsupported"),
    };
    value.is_finite().then_some(value).ok_or("GLB semantic component was not finite")
}

#[derive(Clone, Copy)]
enum RendererAssetProbePhase {
    Reading,
    Parsing,
    Semantic,
    Materializing,
    Ready,
    Closing,
}

struct RendererAssetProbe {
    owner: Option<RendererAssetFetchOwner>,
    prefix: [u8; RENDERER_ASSET_PROBE_BYTES],
    prefix_len: u8,
    observed_bytes: usize,
    page_cursor: RendererAssetPageCursor,
    page_index: RendererAssetPageIndex,
    format: Option<RendererAssetFormatCursor>,
    glb_schema: Option<GlbSchemaCursor>,
    glb_materialize: Option<GlbMaterializeCursor>,
    phase: RendererAssetProbePhase,
    rejection: Option<(&'static str, WorldAssetRequestKind, String)>,
}

/// 🗑️ What a probe step answers. `Reject` and `Fault` both close the response; they differ in WHOSE
/// invariant broke. `Reject` is a verdict about the RESPONSE BYTES — a decoder refused them (wrong
/// format for the kind, truncated structure, dimensions over
/// [`RENDERER_ASSET_PIXEL_BYTES`]) — so exactly one asset is missing and the frame carries on, the way
/// React's loaders leave one texture unpainted. `Fault` is a verdict about the RENDERER — a page
/// cursor lost ownership, a sealed byte witness disagreed, a mesh publication generation was stale —
/// and those quarantine the surface, because nothing downstream can be trusted after them.
enum RendererAssetProbeStep {
    Pending,
    Ready,
    Reject(&'static str),
    Fault(&'static str),
}

impl RendererAssetProbe {
    fn new(owner: RendererAssetFetchOwner) -> Self {
        Self {
            owner: Some(owner),
            prefix: [0; RENDERER_ASSET_PROBE_BYTES],
            prefix_len: 0,
            observed_bytes: 0,
            page_cursor: RendererAssetPageCursor::new(),
            page_index: RendererAssetPageIndex::new(),
            format: None,
            glb_schema: None,
            glb_materialize: None,
            phase: RendererAssetProbePhase::Reading,
            rejection: None,
        }
    }

    fn owner(&self) -> &RendererAssetFetchOwner {
        self.owner.as_ref().expect("asset probe owns response")
    }

    fn owner_mut(&mut self) -> &mut RendererAssetFetchOwner {
        self.owner.as_mut().expect("asset probe owns response")
    }

    fn step(&mut self) -> RendererAssetProbeStep {
        match self.phase {
            RendererAssetProbePhase::Reading => {
                let page = match self.owner.as_ref().expect("asset probe owns response").decode_page() {
                    Ok(Some(page)) => page,
                    Ok(None) => return self.finish_probe(),
                    Err(_) => return self.fault("asset response page cursor lost exact ownership"),
                };
                self.observed_bytes = match self.observed_bytes.checked_add(page.bytes().len()) {
                    Some(bytes) => bytes,
                    None => return self.fault("asset response byte count overflowed"),
                };
                if let Err(detail) = self.page_index.admit(page.bytes().len()) {
                    return self.fault(detail);
                }
                let remaining = RENDERER_ASSET_PROBE_BYTES - usize::from(self.prefix_len);
                let take = remaining.min(page.bytes().len());
                if take != 0 {
                    let start = usize::from(self.prefix_len);
                    self.prefix[start..start + take].copy_from_slice(&page.bytes()[..take]);
                    self.prefix_len += take as u8;
                }
                if self.owner_mut().advance_decode_page().is_err() {
                    return self.fault("asset response page cursor could not advance");
                }
                RendererAssetProbeStep::Pending
            }
            RendererAssetProbePhase::Parsing => {
                let owner = self.owner.as_mut().expect("asset probe owns response");
                let block = match self.page_cursor.read_block(owner) {
                    Ok(Some(block)) => block,
                    Ok(None) => {
                        if let Err(detail) = self.format.as_ref().expect("parsing asset owns format cursor").finish() {
                            return self.reject(detail);
                        }
                        if self.owner_mut().rewind_decode_pages().is_err() {
                            return self.fault("asset response could not rewind after retained structure decode");
                        }
                        self.page_cursor = RendererAssetPageCursor::new();
                        if matches!(self.owner().kind(), WorldAssetRequestKind::Glb) {
                            self.glb_schema = Some(GlbSchemaCursor::new());
                            self.phase = RendererAssetProbePhase::Semantic;
                            return RendererAssetProbeStep::Pending;
                        }
                        self.phase = RendererAssetProbePhase::Ready;
                        return RendererAssetProbeStep::Ready;
                    }
                    Err(detail) => return self.fault(detail),
                };
                if let Err(detail) = self.format.as_mut().expect("parsing asset owns format cursor").feed(&block.0[..usize::from(block.1)]) {
                    return self.reject(detail);
                }
                RendererAssetProbeStep::Pending
            }
            RendererAssetProbePhase::Semantic => {
                let mut schema = self.glb_schema.take().expect("semantic GLB probe owns schema cursor");
                let result = schema.step(self.owner_mut());
                match result {
                    Ok(false) => {
                        self.glb_schema = Some(schema);
                        RendererAssetProbeStep::Pending
                    }
                    Ok(true) => {
                        self.glb_materialize = Some(GlbMaterializeCursor::new(schema.output));
                        self.phase = RendererAssetProbePhase::Materializing;
                        RendererAssetProbeStep::Pending
                    }
                    Err(detail) => self.reject(detail),
                }
            }
            RendererAssetProbePhase::Materializing => {
                let mut materialize = self.glb_materialize.take().expect("GLB probe owns materializer");
                let result = materialize.step(self.owner.as_ref().expect("asset probe owns response"), &self.page_index);
                self.glb_materialize = Some(materialize);
                match result {
                    Ok(false) => RendererAssetProbeStep::Pending,
                    Ok(true) => {
                        self.phase = RendererAssetProbePhase::Ready;
                        RendererAssetProbeStep::Ready
                    }
                    Err(detail) => self.fault(detail),
                }
            }
            RendererAssetProbePhase::Ready => RendererAssetProbeStep::Ready,
            RendererAssetProbePhase::Closing => RendererAssetProbeStep::Pending,
        }
    }

    fn finish_probe(&mut self) -> RendererAssetProbeStep {
        if self.observed_bytes != self.owner().received_bytes() {
            return self.fault("asset response byte witness did not match its sealed claim");
        }
        let prefix_bytes = self.prefix;
        let prefix = &prefix_bytes[..usize::from(self.prefix_len)];
        let valid = match self.owner().kind() {
            WorldAssetRequestKind::Glb => {
                prefix.len() >= 12
                    && &prefix[..4] == b"glTF"
                    && u32::from_le_bytes(prefix[4..8].try_into().expect("fixed GLB version bytes")) == 2
                    && usize::try_from(u32::from_le_bytes(prefix[8..12].try_into().expect("fixed GLB length bytes"))).ok() == Some(self.observed_bytes)
            }
            WorldAssetRequestKind::ReferenceImage => renderer_asset_reference_prefix_is_valid(prefix),
            WorldAssetRequestKind::UiImage { .. } | WorldAssetRequestKind::MapTile { vector: false, .. } => renderer_asset_ui_image_prefix_is_valid(prefix),
            WorldAssetRequestKind::MapTile { vector: true, .. } | WorldAssetRequestKind::Terrain { .. } => self.observed_bytes != 0,
        };
        if !valid {
            return self.reject("asset response format probe rejected malformed input");
        }
        if self.owner_mut().rewind_decode_pages().is_err() {
            return self.fault("asset response could not rewind for its retained decoder");
        }
        self.format = match RendererAssetFormatCursor::new(self.owner().kind(), prefix, self.observed_bytes) {
            Ok(cursor) => Some(cursor),
            Err(detail) => return self.reject(detail),
        };
        self.page_cursor = RendererAssetPageCursor::new();
        self.phase = RendererAssetProbePhase::Parsing;
        RendererAssetProbeStep::Pending
    }

    fn fault(&mut self, detail: &'static str) -> RendererAssetProbeStep {
        self.owner_mut().begin_close();
        self.phase = RendererAssetProbePhase::Closing;
        RendererAssetProbeStep::Fault(detail)
    }

    /// 🗑️ Refuses THIS response and keeps the frame: the kind and url are captured before
    /// `begin_close` clears them, so the lane that requested the asset can record its own miss
    /// (React's `tileMiss`/loader-error shape) instead of re-fetching the same refused bytes forever.
    fn reject(&mut self, detail: &'static str) -> RendererAssetProbeStep {
        self.rejection = Some((detail, self.owner().kind(), self.owner().url().to_string()));
        self.owner_mut().begin_close();
        self.phase = RendererAssetProbePhase::Closing;
        RendererAssetProbeStep::Reject(detail)
    }

    fn take_rejection(&mut self) -> Option<(&'static str, WorldAssetRequestKind, String)> {
        self.rejection.take()
    }

    fn take_ready_mesh_asset(&mut self) -> Option<World3dMeshAsset> {
        (matches!(self.phase, RendererAssetProbePhase::Ready) && matches!(self.owner().kind(), WorldAssetRequestKind::Glb)).then(|| self.glb_materialize.as_mut()?.take_asset()).flatten()
    }

    fn restore_ready_mesh_asset(&mut self, asset: World3dMeshAsset) {
        self.glb_materialize.as_mut().expect("ready GLB probe owns its materializer").restore_asset(asset);
    }

    fn finish_ready_mesh(&mut self) {
        assert!(
            self.glb_materialize.as_ref().is_some_and(|materialize| materialize.lease.is_none() && materialize.appearance.is_none()),
            "published GLB probe relinquished its paged mesh and appearance owners"
        );
        self.owner_mut().begin_close();
        self.phase = RendererAssetProbePhase::Closing;
    }

    fn begin_close(&mut self) {
        if let Some(materialize) = self.glb_materialize.as_mut() {
            materialize.begin_close();
        }
        self.owner_mut().begin_close();
        self.phase = RendererAssetProbePhase::Closing;
    }

    fn close_step(&mut self) -> bool {
        self.begin_close();
        if self.glb_materialize.as_mut().is_some_and(|materialize| !materialize.close_step()) {
            return false;
        }
        self.glb_materialize = None;
        self.owner_mut().close_step()
    }

    fn take_terminal_owner(&mut self) -> Option<RendererAssetFetchOwner> {
        self.owner.as_ref().is_some_and(|owner| owner.owner().terminal_is_empty()).then(|| self.owner.take().expect("terminal probe owner"))
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum RendererAssetDecodeResult {
    Ready,
    Rejected(&'static str),
    Cancelled,
    Fault(&'static str),
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, serde::Serialize)]
#[serde(rename_all = "lowercase")]
pub(crate) enum RendererAssetDecodeTurnKind {
    Idle,
    Pending,
    Published,
    Cancelled,
    Fault,
}

#[derive(serde::Serialize)]
pub(crate) struct RendererAssetDecodeTurn {
    kind: RendererAssetDecodeTurnKind,
    pending: bool,
    #[serde(skip_serializing_if = "Option::is_none")]
    detail: Option<&'static str>,
}

/// 🧵️ Owns one response across bounded decoder turns without borrowing the application runtime.
struct RendererAssetDecodeJob {
    probe: RefCell<Option<RendererAssetProbe>>,
    handback: Arc<Mutex<Option<RendererAssetProbe>>>,
    cancelled: Arc<AtomicBool>,
    result: Option<RendererAssetDecodeResult>,
    steps: u64,
    closing: bool,
}

impl RendererAssetDecodeJob {
    fn new(probe: RendererAssetProbe, cancelled: Arc<AtomicBool>) -> Self {
        Self { probe: RefCell::new(Some(probe)), handback: Arc::new(Mutex::new(None)), cancelled, result: None, steps: 0, closing: false }
    }

    fn take_probe(&self) -> Option<RendererAssetProbe> {
        self.probe.try_borrow_mut().ok()?.take()
    }

    fn complete(&mut self, result: RendererAssetDecodeResult) -> semio_framework_job::StepOutcome {
        use semio_framework_job::{CommitCandidate, JobPayloadStream, RetainedJobPayload, StepOutcome};
        self.result = Some(result);
        StepOutcome::Complete(CommitCandidate { state: RetainedJobPayload::empty(JobPayloadStream::CommitState), output: RetainedJobPayload::empty(JobPayloadStream::CommitOutput) })
    }
}

impl semio_framework_job::InteractiveJob for RendererAssetDecodeJob {
    fn step(&mut self, context: &mut semio_framework_job::StepContext<'_>) -> semio_framework_job::StepOutcome {
        use semio_framework_job::StepOutcome;
        if self.cancelled.load(Ordering::Acquire) || context.is_cancelled() {
            return self.complete(RendererAssetDecodeResult::Cancelled);
        }
        if context.should_yield() {
            return StepOutcome::Yield;
        }
        let Some(steps) = self.steps.checked_add(1) else {
            return self.complete(RendererAssetDecodeResult::Fault("asset decode step sequence exhausted"));
        };
        let Some(probe) = self.probe.get_mut().as_mut() else {
            return self.complete(RendererAssetDecodeResult::Fault("asset decode lost its exact response owner"));
        };
        let result = probe.step();
        self.steps = steps;
        context.consume_fuel(1);
        match result {
            RendererAssetProbeStep::Pending => StepOutcome::Yield,
            RendererAssetProbeStep::Ready => self.complete(RendererAssetDecodeResult::Ready),
            RendererAssetProbeStep::Reject(detail) => self.complete(RendererAssetDecodeResult::Rejected(detail)),
            RendererAssetProbeStep::Fault(detail) => self.complete(RendererAssetDecodeResult::Fault(detail)),
        }
    }

    fn begin_close(&mut self) {
        self.closing = true;
        self.result = None;
    }

    fn close_step(&mut self, maximum_items: usize, _maximum_bytes: usize) -> semio_framework_job::InteractiveJobCloseStep {
        use semio_framework_job::InteractiveJobCloseStep;
        self.begin_close();
        if self.probe.get_mut().is_none() {
            return InteractiveJobCloseStep::Complete;
        }
        if maximum_items == 0 {
            return InteractiveJobCloseStep::Pending { released_items: 0, released_bytes: 0 };
        }
        let Ok(mut handback) = self.handback.try_lock() else {
            return InteractiveJobCloseStep::Pending { released_items: 0, released_bytes: 0 };
        };
        if handback.is_some() {
            return InteractiveJobCloseStep::Pending { released_items: 0, released_bytes: 0 };
        }
        *handback = self.probe.get_mut().take();
        InteractiveJobCloseStep::Pending { released_items: 1, released_bytes: 0 }
    }

    fn terminal_is_empty(&self) -> bool {
        self.closing && self.result.is_none() && self.probe.borrow().is_none()
    }
}

#[cfg(not(target_arch = "wasm32"))]
struct RendererAssetDecodeWake(RuntimeHostWaker);

#[cfg(not(target_arch = "wasm32"))]
impl std::task::Wake for RendererAssetDecodeWake {
    fn wake(self: Arc<Self>) {
        (self.0)();
    }
    fn wake_by_ref(self: &Arc<Self>) {
        (self.0)();
    }
}

/// 📬️ Retains the exact decoder ticket and all rejected or terminal response handbacks.
struct RendererAssetDecodeSession {
    session: Option<semio_framework_job::WorkerJobSession<RendererAssetDecodeJob>>,
    rejected: Option<semio_framework_job::WorkerJobSessionAdmissionRejected<RendererAssetDecodeJob>>,
    ticket: Option<semio_framework_job::WorkerJobTicket>,
    handback: Arc<Mutex<Option<RendererAssetProbe>>>,
    boundary: Option<(RendererAssetProbe, Option<RendererAssetDecodeResult>)>,
    cancelled: Arc<AtomicBool>,
    surface_token: Option<AdmittedSurfaceToken>,
    request_token: WorldAssetRequestToken,
    fault: Option<&'static str>,
    #[cfg(not(target_arch = "wasm32"))]
    waker: Option<std::task::Waker>,
}

impl RendererAssetDecodeSession {
    fn new(probe: RendererAssetProbe, wake: Option<RuntimeHostWaker>) -> Self {
        use semio_framework_job::{allocate_operation_id, root_cancel_token, BatchDriveConfig, BatchJobParams, Generation, InteractiveStage, WorkerJobSession};
        let surface_token = match probe.owner() {
            RendererAssetFetchOwner::World { surface_token, .. } => Some(*surface_token),
            RendererAssetFetchOwner::Shared(_) => None,
        };
        let request_token = probe.owner().owner().token();
        let cancelled = Arc::new(AtomicBool::new(false));
        let job = RendererAssetDecodeJob::new(probe, cancelled.clone());
        let handback = job.handback.clone();
        let params = BatchJobParams {
            operation: allocate_operation_id(),
            generation: Generation(1),
            cancel: root_cancel_token(),
            config: BatchDriveConfig { site: "renderer_asset_decode", stage: InteractiveStage::InteractiveStep, fuel_per_step: 1, step_budget_us: semio_framework_job::INTERACTIVE_LANE_WALL_US },
            now_us: semio_framework_job::default_now_us,
        };
        let (session, rejected, boundary) = match WorkerJobSession::try_new(job, params) {
            Ok(session) => (Some(session), None, None),
            Err(mut rejected) => {
                let boundary = rejected.job().take_probe().map(|probe| (probe, None));
                rejected.begin_close();
                (None, Some(rejected), boundary)
            }
        };
        #[cfg(target_arch = "wasm32")]
        let _ = wake;
        Self {
            session,
            rejected,
            ticket: None,
            handback,
            boundary,
            cancelled,
            surface_token,
            request_token,
            fault: None,
            #[cfg(not(target_arch = "wasm32"))]
            waker: wake.map(|wake| std::task::Waker::from(Arc::new(RendererAssetDecodeWake(wake)))),
        }
    }

    fn cancel(&self) {
        if !self.cancelled.swap(true, Ordering::AcqRel) {
            self.wake();
        }
    }

    fn wake(&self) {
        #[cfg(not(target_arch = "wasm32"))]
        if let Some(waker) = self.waker.as_ref() {
            waker.wake_by_ref();
        }
    }

    fn pump_one(&mut self) -> bool {
        use semio_framework_job::{StepOutcome, WorkerJobPoll};
        if self.boundary.is_none() {
            if let Ok(mut handback) = self.handback.try_lock() {
                self.boundary = handback.take().map(|probe| (probe, Some(self.fault.map_or(RendererAssetDecodeResult::Cancelled, RendererAssetDecodeResult::Fault))));
            }
        }
        if let Some(rejected) = self.rejected.as_mut() {
            let _ = rejected.close_step(1, semio_framework_job::JOB_PAYLOAD_PAGE_BYTES);
            if rejected.terminal_is_empty() {
                self.rejected = None;
            }
            return true;
        }
        let Some(session) = self.session.as_ref() else { return false };
        let _ = session.take_wake();
        #[cfg(not(target_arch = "wasm32"))]
        if self.waker.as_ref().is_some_and(|waker| session.register_wake(waker).is_err()) {
            return true;
        }
        match session.poll() {
            WorkerJobPoll::Idle => {
                #[cfg(not(target_arch = "wasm32"))]
                match session.try_submit_step(&renderer_worker_pool(), semio_framework_async::Lane::Maintenance) {
                    Ok(ticket) => {
                        self.ticket = Some(ticket);
                        return false;
                    }
                    Err(semio_framework_job::WorkerJobSubmitFault::SequenceExhausted) => {
                        self.fault = Some("asset decoder session sequence exhausted");
                        let _ = session.begin_close();
                    }
                    Err(_) => {}
                }
                #[cfg(target_arch = "wasm32")]
                match session.try_step_on_worker() {
                    Ok((ticket, _)) => self.ticket = Some(ticket),
                    Err(semio_framework_job::WorkerJobContention::WakeExhausted(_)) => {
                        self.fault = Some("asset decoder session wake sequence exhausted");
                        let _ = session.begin_close();
                    }
                    Err(_) => {}
                }
            }
            WorkerJobPoll::Outcome => {
                let Some(ticket) = self.ticket else {
                    self.fault = Some("asset decoder outcome lost its exact ticket");
                    let _ = session.begin_close();
                    return true;
                };
                if let Ok(mut owner) = session.take_outcome(ticket) {
                    self.ticket = None;
                    if matches!(owner.outcome(), StepOutcome::Yield) {
                        let _ = owner.take_outcome();
                        if let Err(owner) = owner.resume() {
                            self.fault = Some("asset decoder yield could not resume its exact owner");
                            owner.begin_close();
                        }
                    } else {
                        self.fault = Some("asset decoder exposed a nonterminal payload");
                        owner.begin_close();
                    }
                }
            }
            WorkerJobPoll::Terminal => {
                if let Ok(owner) = session.take_terminal() {
                    let result = match owner.outcome() {
                        StepOutcome::Complete(_) => owner.job().result.unwrap_or(RendererAssetDecodeResult::Fault("asset decoder completed without its typed result")),
                        StepOutcome::Cancelled => RendererAssetDecodeResult::Cancelled,
                        _ => RendererAssetDecodeResult::Fault("asset decoder worker terminated with a fault"),
                    };
                    self.boundary = owner.job().take_probe().map(|probe| (probe, Some(result)));
                    self.ticket = None;
                    owner.begin_close();
                }
            }
            WorkerJobPoll::Rejected => {
                if let Ok(rejected) = session.take_rejected() {
                    match rejected.kind() {
                        semio_framework_async::WorkerSubmitErrorKind::Saturated | semio_framework_async::WorkerSubmitErrorKind::Contended => rejected.resume(),
                        _ => {
                            self.fault = Some("asset decoder worker pool refused the exact submission");
                            self.boundary = rejected.job().take_probe().map(|probe| (probe, Some(RendererAssetDecodeResult::Fault("asset decoder worker pool refused the exact submission"))));
                            rejected.begin_close();
                        }
                    }
                }
            }
            WorkerJobPoll::Closing | WorkerJobPoll::TerminalEmpty => {
                let _ = session.close_step(1, semio_framework_job::JOB_PAYLOAD_PAGE_BYTES);
                if session.terminal_is_empty() {
                    self.session = None;
                }
            }
            WorkerJobPoll::Submitted | WorkerJobPoll::CheckedOut => return false,
        }
        true
    }

    fn take_boundary(&mut self) -> Option<(RendererAssetProbe, Option<RendererAssetDecodeResult>)> {
        if self.session.is_some() || self.rejected.is_some() {
            return None;
        }
        let (probe, result) = self.boundary.take()?;
        Some((probe, if self.cancelled.load(Ordering::Acquire) && !matches!(result, Some(RendererAssetDecodeResult::Fault(_))) { Some(RendererAssetDecodeResult::Cancelled) } else { result }))
    }

    fn terminal_is_empty(&self) -> bool {
        self.session.is_none() && self.rejected.is_none() && self.boundary.is_none() && self.handback.try_lock().is_ok_and(|owner| owner.is_none())
    }
}

fn renderer_asset_svg_prefix_is_valid(prefix: &[u8]) -> bool {
    std::str::from_utf8(prefix).ok().is_some_and(|text| {
        let text = text.trim_start_matches(|character: char| character.is_ascii_whitespace());
        text.starts_with("<svg") || text.starts_with("<?xml")
    })
}

fn renderer_asset_ui_image_prefix_is_valid(prefix: &[u8]) -> bool {
    prefix.starts_with(b"\x89PNG\r\n\x1a\n") || prefix.starts_with(&[0xff, 0xd8, 0xff]) || renderer_asset_svg_prefix_is_valid(prefix)
}

fn renderer_asset_reference_prefix_is_valid(prefix: &[u8]) -> bool {
    renderer_asset_ui_image_prefix_is_valid(prefix)
        || prefix.starts_with(b"GIF87a")
        || prefix.starts_with(b"GIF89a")
        || (prefix.len() >= 12 && &prefix[..4] == b"RIFF" && &prefix[8..12] == b"WEBP")
        || prefix.starts_with(b"BM")
        || prefix.starts_with(b"II*\0")
        || prefix.starts_with(b"MM\0*")
        || prefix.starts_with(b"II+\0")
        || prefix.starts_with(b"MM\0+")
        || prefix.starts_with(b"%PDF-")
        || (prefix.len() >= 12 && &prefix[4..8] == b"ftyp")
}
