/// 🪲️ Regression law for the two-frame `to_value` → `to_dsl_value` → `to_value` recursion that made
/// every `NativeSocketProbe*` encode abort the process with `fatal runtime error: stack overflow`:
/// reaching an assertion at all proves the cycle is gone, and the fixture pins the exact wire shape
/// so the cure cannot silently change the encoding. `serde_json` is the independent third-party
/// oracle — the first-party `ToValue` tree must equal what it serializes for the same values.

#[cfg(not(target_arch = "wasm32"))]
impl store::os_spr::OpText for NativeSocketProbeMutation {
    fn print_op(&self) -> String {
        let Self::Set(value) = self;
        value.clone()
    }

    fn parse_op(line: &str) -> Result<Self, store::os_store::TextError> {
        Ok(Self::Set(line.to_string()))
    }
}

#[cfg(not(target_arch = "wasm32"))]
impl store::os_spr::OpBinary for NativeSocketProbeMutation {
    fn encode_op(&self) -> Result<Vec<u8>, store::os_spr::ProtocolError> {
        let Self::Set(value) = self;
        Ok(value.as_bytes().to_vec())
    }

    fn decode_op(bytes: &[u8]) -> Result<Self, store::os_spr::ProtocolError> {
        String::from_utf8(bytes.to_vec()).map(Self::Set).map_err(|error| store::os_spr::ProtocolError::Malformed { what: "native-socket-probe-op", offset: 0, detail: error.to_string() })
    }
}

#[cfg(not(target_arch = "wasm32"))]
pub async fn run_socket_grant_probe() -> i32 {
    use dsl::os_directory::client::{native::NativeDirectoryTransport, DirectoryClient};
    use dsl::os_directory::identity::claimed_local_hub_credential;
    use dsl::os_spr::{ActorId, ArtifactDiff, ArtifactId, HybridLogicalTimestamp, InverseMutation, MutationEnvelope, MutationId, SchemaId};
    use dsl::os_store::sync::{ArtifactActorConfig, ArtifactActorMsg, ArtifactDocumentKey, ArtifactEvent, ArtifactHost, CommandAckOutcome, PersistenceBinding};
    use semio_framework_actor::{ActorId as DirectoryActorId, PackageId as DirectoryPackageId};
    use semio_framework_async::ScopeOwner;
    use semio_framework_os_services::{ComputePool, TokioHostRuntime};

    const PROBE_SCHEMA: &str = "native.socket-grant.probe/v1";
    let Some(credential) = claimed_local_hub_credential("native") else { return 1 };
    let _ = dsl::os_store::register_document_codec(dsl::os_store::ArtifactCodec::of::<NativeSocketProbeSnapshot, NativeSocketProbeMutation>(PROBE_SCHEMA));
    let pool = renderer_worker_pool();
    let runtime = Arc::new(TokioHostRuntime::with_pool(pool.clone()));
    let scope = runtime.open_scope_now(ScopeOwner::Service("native_socket_grant_probe"), None);
    let compute = Arc::new(ComputePool::with_pool(2, pool.clone()));
    let transport = NativeDirectoryTransport::with_new_http_pool_now(runtime, scope, compute, 1_000_000, 2, DirectoryPackageId("native.socket-grant-probe".into()), DirectoryActorId(0));
    let client = Arc::new(DirectoryClient::authenticated(transport, credential.clone()));
    let host = ArtifactHost::new(Arc::new(pool));
    if host.local_hub_ready() {
        return 1;
    }
    host.set_local_hub_credential(credential.clone());
    if host.local_hub_ready() {
        return 1;
    }
    host.set_hub_socket_grant_source(client);
    if !host.local_hub_ready() {
        return 1;
    }
    let document_id = "probe-document";
    let document_key = ArtifactDocumentKey::hub("probe-space", document_id);
    let _ = &document_key;
    let channels = host
        .open(ArtifactActorConfig {
            document_id: document_id.into(),
            schema: PROBE_SCHEMA.into(),
            bindings: vec![PersistenceBinding::Hub { base_url: credential.hub_origin().into(), space_id: "probe-space".into(), surface: Some("native.socket-grant.probe.editor".into()) }],
            watch_external: false,
            actor: "untrusted-local-probe".into(),
        })
        .await;
    let mut events = host.subscribe_key(&channels.document_key).await;
    let deadline = std::time::Instant::now() + std::time::Duration::from_secs(12);
    let mut sessions = 0u8;
    let mut acknowledgements = 0u8;
    let envelope = |sequence: u8| MutationEnvelope {
        mutation_id: MutationId(format!("probe-{sequence}")),
        document_id: ArtifactId(document_id.into()),
        actor: ActorId("untrusted-local-probe".into()),
        dependencies: Vec::new(),
        observed: None,
        target: Vec::new(),
        diff: ArtifactDiff { schema: SchemaId(PROBE_SCHEMA.into()), payload: vec![sequence] },
        inverse: InverseMutation { schema: SchemaId(PROBE_SCHEMA.into()), payload: Vec::new() },
        timestamp: HybridLogicalTimestamp::new(0, 0),
        transaction: None,
        verb: None,
        line: None,
    };
    if channels.cmd_tx.send(ArtifactActorMsg::LocalMutations { envelopes: vec![envelope(1)] }).is_err() {
        host.close_key(&channels.document_key);
        return 1;
    }
    while std::time::Instant::now() < deadline {
        match events.try_recv() {
            Ok(ArtifactEvent::Session { .. }) => {
                sessions += 1;
                if sessions == 2 && channels.cmd_tx.send(ArtifactActorMsg::LocalMutations { envelopes: vec![envelope(2)] }).is_err() {
                    break;
                }
            }
            Ok(ArtifactEvent::CommandOutcome { outcome: CommandAckOutcome::Accepted, .. }) => {
                acknowledgements += 1;
                if acknowledgements == 2 {
                    host.close_key(&channels.document_key);
                    return 0;
                }
            }
            Ok(_) | Err(tokio::sync::broadcast::error::TryRecvError::Empty) | Err(tokio::sync::broadcast::error::TryRecvError::Lagged(_)) => {}
            Err(tokio::sync::broadcast::error::TryRecvError::Closed) => break,
        }
        std::thread::sleep(std::time::Duration::from_millis(10));
    }
    host.close_key(&channels.document_key);
    1
}

#[cfg(not(target_arch = "wasm32"))]
pub fn run_native(plugin_filter: &str, plugin_modules_root: std::path::PathBuf, services:Vec<semio_framework_os_kernel::os_directory::client::InstalledServiceContributionV1>) {
    scenes::install_native_host_temporal_formatter(std::sync::Arc::new(native_temporal::SystemTemporalFormatter::default()));
    let event_loop = EventLoop::<winit_app::HostUserEvent>::with_user_event().build().expect("event loop");
    let proxy = event_loop.create_proxy();
    let mut app = winit_app::WinitApp::new(proxy, plugin_filter.to_string(), plugin_modules_root,services);
    let _ = event_loop.run_app(&mut app);
}

/// 🧪️ ticket 26/08/17/FINISH-HUB-SPACES-COLLABORATION-END-TO-END — headless smoke mode: boots
/// `ShellState` against a live hub (`S_HUB_URL`/`S_USER`/`S_DATA_DIR`) with NO GPU/window at all —
/// `GpuContext`/`winit`/`AppRuntime` are the only GPU-coupled pieces in this crate and this mode never
/// touches any of them, since `ShellState` itself is renderer-agnostic (chrome painting is a separate
/// concern layered on top by `AppRuntime::frame`). Boots, waits (bounded) for identity to mint/restore
/// and the initial directory fold to land, then dumps the Home window's widget tree + a small identity/
/// session summary as JSON to stdout and returns an exit code. An honest, explicit substitute for
/// driving a real window when this environment cannot open one (lane 3-D's brief proposed exactly this
/// shape). Returns `0` on a clean boot+dump, `1` on any hard failure along the way.
///
/// 🪪️ Identity mint/restore runs on a background OS thread (contract §C3: never blocks
/// `boot()` itself) — poll the same every-frame pump the real render loop uses (drains the
/// identity bootstrap channel + the directory stream + folds any pending events) for up to 5s
/// so a real hub round trip has time to land before the dump.
#[cfg(not(target_arch = "wasm32"))]
pub async fn run_smoke(plugin_filter: &str, plugin_modules_root: std::path::PathBuf,services:Vec<semio_framework_os_kernel::os_directory::client::InstalledServiceContributionV1>) -> i32 {
    let axes = match shell::shell_language_axes() {
        Ok(axes) => axes,
        Err(error) => { eprintln!("smoke: {error}"); return 1; }
    };
    run_smoke_with_axes(plugin_filter,plugin_modules_root,services,axes).await
}

/// 🧭️ Boots the exact selected native plugin under caller-declared presentation axes.
#[cfg(not(target_arch = "wasm32"))]
pub(crate) async fn run_smoke_with_axes(plugin_filter: &str, plugin_modules_root: std::path::PathBuf,services:Vec<semio_framework_os_kernel::os_directory::client::InstalledServiceContributionV1>,axes:(semio_framework_ui_locale::Locale,semio_framework_ui_locale::Terminology)) -> i32 {
    let loaded = match load_wasm_plugins(plugin_filter, &plugin_modules_root).await {
        Ok(entries) => entries,
        Err(error) => {
            eprintln!("smoke: load_wasm_plugins failed: {error}");
            return 1;
        }
    };
    let entries = filter_plugins(loaded, plugin_filter);
    let (locale, terminology) = axes;
    let mut shell = ShellState::new(entries, plugin_filter.to_string(), locale, terminology);
    shell.install_document_services(services);
    if let Err(error) = shell.boot().await {
        eprintln!("smoke: shell.boot() failed: {error}");
        return 1;
    }
    let deadline = std::time::Instant::now() + std::time::Duration::from_secs(5);
    while std::time::Instant::now() < deadline {
        shell.pump_sync_events().await;
        if shell.identity.is_some() || shell.identity_env.is_none() {
            break;
        }
        std::thread::sleep(std::time::Duration::from_millis(100));
    }
    let _ = shell.refresh_ui(semio_framework::kernel::UiDirtyScope::Full).await;
    let identity_summary = shell.identity.as_ref().map(|identity| serde_json::json!({ "userId": identity.user_id, "email": identity.email, "hubBaseUrl": identity.hub_base_url }));
    let window_documents: Vec<_> = shell.window_ui.iter().map(|(window, document)| serde_json::json!({ "window": window, "generation": document.generation() })).collect();
    let booted = plugin_filter.is_empty() || shell.session.is_some();
    let report = serde_json::json!({
        "booted": booted,
        "identity": identity_summary,
        "identityOffline": shell.identity_offline,
        "openSpaceId": shell.open_space_id,
        "session": shell.session.as_ref().map(|session| serde_json::json!({ "pluginId": session.plugin_id, "appId": session.app.id, "role": format!("{:?}", session.app.role) })),
        "windowDocuments": window_documents,
    });
    match serde_json::to_string_pretty(&report) {
        Ok(json) => {
            println!("{json}");
            i32::from(!booted)
        }
        Err(error) => {
            eprintln!("smoke: report encode failed: {error}");
            1
        }
    }
}

/// 🐚️ Multi-mount: takes an already-created, already-placed canvas from the caller instead of looking
/// up a hardcoded `#root`/`#semio-wgpu-canvas` and taking it over via `set_inner_html("")` — that
/// single-mount assumption meant a second boot call would wipe the first mount's canvas and collide on
/// the same DOM id. The caller (`bootFrameworkOsWgpu` in `🟦️.ts`) now owns creating and placing
/// the canvas, so N independent mounts can coexist on one page.
///
/// Known gap (not yet done — see the plan's Wave 6 D11 notes), **narrowed but not closed** by ticket
/// 26/08/20/SEMANTIC-UI-CONTRACT-AND-RENDERER-FAMILY (packet os-host): the independent, uncancellable
/// `start_frame_loop`/`schedule_frame` recursive `requestAnimationFrame` chain this comment used to
/// describe is DELETED — every redraw now goes through `winit`'s own event loop
/// (`event_loop.spawn_app(app)` below → `winit_app::WinitApp`), and `WindowEvent::CloseRequested`
/// already calls `ActiveEventLoop::exit()`. Whether `exit()` alone now fully tears down a wasm mount
/// (winit's own wasm backend's post-`exit()` behaviour) is UNVERIFIED — this crate still does not
/// build clean (U4, `📓️terra-os-host-report.md`), so a real `semioWgpuUnmount` handle remains
/// deferred, but the mechanism it would need to cancel no longer exists in its old shape.
/// The dozen-plus `thread_local!` globals further up this file (`UI_ENGINE`, `ENGINE_SURFACES`,
/// `SCENE_STATE`, tooltip/dialog/tour chrome state, clipboard mocks, prefs, image-fetch caches, …) are
/// also still page-global, not per-mount — two simultaneous wgpu mounts each render on their own
/// independent GPU device/queue/surface (real, working isolation), but would still cross-talk on shared
/// UI chrome auxiliary state (a tooltip or dialog opened in one mount could show in the other).
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen(js_name = uploadIconAtlas)]
pub fn upload_icon_atlas(width: u32, height: u32, pixels: &[u8], entries_json: &str) -> Result<(), JsValue> {
    let entries_map: std::collections::HashMap<String, [f32; 4]> = serde_json::from_str(entries_json).map_err(|err| JsValue::from_str(&format!("icon entries parse: {err}")))?;
    let entries: Vec<(String, [f32; 4])> = entries_map.into_iter().collect();
    ICON_ATLAS_RUNTIME.with(|cell| {
        cell.borrow_mut().replace(IconAtlas::from_packed(width, height, pixels.to_vec(), entries));
    });
    Ok(())
}

thread_local! {
    static ICON_ATLAS_RUNTIME: RefCell<Option<IconAtlas>> = RefCell::new(None);
}

//#region 🧭️BootDescriptor
// 🧭️ ONE boot-axis vocabulary for all three wgpu entry points — the trunk page
// (`🚀️browser-boot/🟦️.ts`), the embeddable library door (`🎬️renderer-boot/🟦️.ts`) and the native CLI
// (`⌨️native-entrypoint/🦀️.rs`) — and the Rust twin of `🧭️boot-descriptor/🟦️.ts`. React has a single
// door (`FrameworkOsBootOptions`); wgpu had three, each carrying a different subset of the same axes,
// so `--plugin cad --example concrete-forest` could not open natively what
// `?plugin=cad&example=concrete-forest` opened in the browser. The standing law that keeps the four
// field sets equal is `🧪️tests/🧭️boot-axis-parity/🦀️.rs`.
//
// Still a `thread_local` a caller opts into reading rather than a parameter threaded through every
// mount signature: the shell reads it while it opens the session (`ShellState::boot`), which is why
// every door applies it BEFORE mounting.

/// 📏️ Bound on ONE descriptor field, the twin of `🧭️boot-descriptor/🟦️.ts`'s
/// `WGPU_BOOT_FIELD_CAPACITY` — the browser door refuses an oversized url before it ever reaches
/// here, and this is the same refusal for the native and library doors.
pub const WGPU_BOOT_FIELD_CAPACITY: usize = 2048;

/// 🔒️ Boot-time preference LOCKS — React's `FrameworkOsLocks`. `""` means unset, never "locked to the
/// empty string"; a locked preference loses its in-app switcher.
#[derive(Clone, Debug, Default, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
#[serde(rename_all = "camelCase", default)]
pub struct WgpuBootLocks {
    pub example_id: String,
    pub locale: String,
    pub terminology: String,
    pub theme_id: String,
    pub appearance: String,
}

/// 🎛️ Boot-time preference DEFAULTS — React's `FrameworkOsDefaults`: seeds that KEEP their switcher.
#[derive(Clone, Debug, Default, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
#[serde(rename_all = "camelCase", default)]
pub struct WgpuBootDefaults {
    pub example_id: String,
}

/// 🏷️ The brand REGISTRY row this boot resolved — React's `resolveShellBrandById(brandId)` answer
/// (`🧑‍💻dev/🏷️brand/🟦️.ts`), reduced to the facts the shell itself reads. The table stays where it is
/// (a TypeScript catalogue over the demonstrator's own brand definitions); what crosses into the
/// renderer is the resolved ROW, exactly as `locks`/`defaults` already do — so a brand added there
/// needs no Rust edit and the two halves cannot drift into two catalogues.
///
/// `brand_id` alone was carried before this (`📓️w1d-boot-axis-parity.md` gap 1): the shell knew it was
/// branded and nothing else, which is why the tour's persisted-seen key dropped React's brand prefix
/// on every branded playground (`📓️w5a-browser-prefs-persistence.md` §7.1, demonstrated on
/// `aggregator`).
#[derive(Clone, Debug, Default, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
#[serde(rename_all = "camelCase", default)]
pub struct WgpuBootBrand {
    /// 🏷️ React's `ShellBrand.windowTitle` — the native window's title; `""` leaves the default.
    pub window_title: String,
    /// 🧊️ React's `ShellBrand.ephemeral`: the shell never reads or writes device-local state.
    pub ephemeral: bool,
    /// 🎓️ React's `ShellBrand.replayIntroductionOnLoad` — auto-start every load, persist no seen flag.
    /// `isEphemeralShellBrand` implies it there, and [`WgpuBootBrand::replays_introduction`] implies it
    /// here, so the two predicates cannot disagree.
    pub replay_introduction_on_load: bool,
}

impl WgpuBootBrand {
    /// 🎓️ React's `shouldReplayIntroductionOnLoad(brand)`.
    pub fn replays_introduction(&self) -> bool {
        self.ephemeral || self.replay_introduction_on_load
    }

    /// 🎓️ React's `shouldPersistIntroductionSeen(brand)`.
    pub fn persists_introduction_seen(&self) -> bool {
        !self.replays_introduction()
    }
}

/// 🌐️ The hub trio (`?hub=&user=&dataDir=`, `--hub/--user/--data-dir`).
#[derive(Clone, Debug, Default, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
#[serde(rename_all = "camelCase", default)]
pub struct WgpuBootHub {
    pub hub_url: String,
    pub user: String,
    pub data_dir: String,
}

/// 🧭️ Every boot axis, resolved. Absent axes are `""`/`Default` rather than `Option`, so the three
/// doors cannot disagree about what "unset" serializes to.
#[derive(Clone, Debug, Default, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
#[serde(rename_all = "camelCase", default)]
pub struct WgpuBootDescriptor {
    pub plugin_variant: String,
    pub app_id: String,
    pub app_role: String,
    pub app_mode: String,
    pub app_example: String,
    pub brand_id: String,
    pub brand: WgpuBootBrand,
    pub broker_proof: String,
    pub locks: WgpuBootLocks,
    pub defaults: WgpuBootDefaults,
    pub hub: Option<WgpuBootHub>,
}

impl WgpuBootDescriptor {
    /// 📏️ Refuses an oversized field by NAME, so the fault says which axis overflowed — the Rust half
    /// of `boundedBootField`. Applied before any axis is stored, never after.
    pub fn validated(self) -> Result<Self, String> {
        let hub = self.hub.as_ref();
        let fields: [(&str, &str); 14] = [
            ("plugin", self.plugin_variant.as_str()),
            ("app", self.app_id.as_str()),
            ("role", self.app_role.as_str()),
            ("mode", self.app_mode.as_str()),
            ("example", self.app_example.as_str()),
            ("brand", self.brand_id.as_str()),
            ("brand.windowTitle", self.brand.window_title.as_str()),
            ("brokerProof", self.broker_proof.as_str()),
            ("locks.exampleId", self.locks.example_id.as_str()),
            ("locks.locale", self.locks.locale.as_str()),
            ("locks.terminology", self.locks.terminology.as_str()),
            ("locks.themeId", self.locks.theme_id.as_str()),
            ("locks.appearance", self.locks.appearance.as_str()),
            ("defaults.exampleId", self.defaults.example_id.as_str()),
        ];
        let hub_fields: [(&str, &str); 3] = [("hub", hub.map_or("", |hub| hub.hub_url.as_str())), ("user", hub.map_or("", |hub| hub.user.as_str())), ("dataDir", hub.map_or("", |hub| hub.data_dir.as_str()))];
        for (field, value) in fields.into_iter().chain(hub_fields) {
            if value.chars().count() > WGPU_BOOT_FIELD_CAPACITY {
                return Err(format!("boot-descriptor-overflow: {field} exceeds {WGPU_BOOT_FIELD_CAPACITY} code units"));
            }
        }
        Ok(self)
    }
}

thread_local! {
    static BOOT_DESCRIPTOR: RefCell<WgpuBootDescriptor> = RefCell::new(resolve_environment_boot_descriptor());
}

/// 🖥️ The native per-server seeds, read straight off the process env under the SAME names React's
/// serve projects into `VITE_SEMIO_*` (`🧑‍💻dev/🟦️.ts`). The CLI's own per-navigation flags overwrite
/// these in `apply_boot_descriptor`; a browser build has no process env and starts empty.
///
/// 🏷️ The resolved brand ROW, under the same `SEMIO_*` names the serve injects as
/// `<meta semio-brand-*>` for the browser door — one vocabulary, three doors.
#[cfg(not(target_arch = "wasm32"))]
fn resolve_environment_boot_descriptor() -> WgpuBootDescriptor {
    let read = |name: &str| std::env::var(name).ok().filter(|value| !value.is_empty()).unwrap_or_default();
    WgpuBootDescriptor {
        app_id: read("SEMIO_APP_ID"),
        app_role: read("SEMIO_APP_ROLE"),
        brand_id: read("SEMIO_BRAND"),
        brand: WgpuBootBrand { window_title: read("SEMIO_BRAND_WINDOW_TITLE"), ephemeral: read("SEMIO_BRAND_EPHEMERAL") == "true", replay_introduction_on_load: read("SEMIO_BRAND_REPLAY_INTRODUCTION") == "true" },
        app_example: read("SEMIO_DEFAULT_EXAMPLE"),
        defaults: WgpuBootDefaults { example_id: read("SEMIO_DEFAULT_EXAMPLE") },
        locks: WgpuBootLocks { example_id: read("SEMIO_LOCKED_EXAMPLE"), locale: read("SEMIO_LOCKED_LOCALE"), terminology: read("SEMIO_LOCKED_TERMINOLOGY"), theme_id: read("SEMIO_LOCKED_THEME"), appearance: read("SEMIO_LOCKED_APPEARANCE") },
        ..WgpuBootDescriptor::default()
    }
}

#[cfg(target_arch = "wasm32")]
fn resolve_environment_boot_descriptor() -> WgpuBootDescriptor {
    WgpuBootDescriptor::default()
}

/// 🧭️ Installs the resolved axes, replacing the environment seeds this thread started from. Every
/// door calls it once, before the mount that opens the session.
pub fn apply_boot_descriptor(descriptor: WgpuBootDescriptor) -> Result<(), String> {
    let descriptor = descriptor.validated()?;
    BOOT_DESCRIPTOR.with(|cell| *cell.borrow_mut() = descriptor);
    Ok(())
}

/// 🌐️ wasm boot hook — the frame Worker (`🎞️frame-worker/🟦️.ts`) and the page-mounted library door
/// (`🎬️renderer-boot/🟦️.ts`) each call this once with the JSON `🧭️boot-descriptor/🟦️.ts` resolved.
/// 🩺️ wasm diagnostics hook — the browser twin of the `SEMIO_RUNTIME_DIAGNOSTICS` environment
/// variable a native process reads and of the `localStorage` key React's `ShellHost` reads. A Worker
/// realm owns neither, so the UI isolate resolves the preference, stamps it on the frame Worker's url
/// (`🎭️actor/🩺️diagnostics/🟦️.ts`'s `stampShardWorkerDiagnostics`) and the Worker hands it here —
/// before the first frame, because every per-frame `[TRACE]` dump in this crate is gated on it.
#[cfg(target_arch = "wasm32")]
#[wasm_bindgen(js_name = semioWgpuSetRuntimeDiagnostics)]
pub fn semio_wgpu_set_runtime_diagnostics(enabled: bool) {
    semio_framework_trace::set_runtime_diagnostics(enabled);
}

#[cfg(target_arch = "wasm32")]
#[wasm_bindgen(js_name = semioWgpuSetBootDescriptor)]
pub fn semio_wgpu_set_boot_descriptor(descriptor_json: String) -> Result<(), JsValue> {
    let descriptor: WgpuBootDescriptor = serde_json::from_str(&descriptor_json).map_err(|error| JsValue::from_str(&format!("boot-descriptor parse: {error}")))?;
    apply_boot_descriptor(descriptor).map_err(|error| JsValue::from_str(&error))
}

/// 🧭️ The whole resolved descriptor, for a reader that needs more than one axis.
pub fn boot_descriptor() -> WgpuBootDescriptor {
    BOOT_DESCRIPTOR.with(|cell| cell.borrow().clone())
}

fn boot_axis(read: impl Fn(&WgpuBootDescriptor) -> &str) -> Option<String> {
    BOOT_DESCRIPTOR.with(|cell| {
        let descriptor = cell.borrow();
        let value = read(&descriptor);
        (!value.is_empty()).then(|| value.to_string())
    })
}

/// 📌️ The boot-pinned app id, or `None`. React's `appId`: an empty value is NOT a pin, it falls
/// through to the variant's own default app (`🧑‍💻dev/🟦️.ts`'s own note on `VITE_SEMIO_APP_ID`).
pub fn boot_app_id() -> Option<String> {
    boot_axis(|descriptor| &descriptor.app_id)
}

/// 🎭️ The boot-requested mode id, or `None` when nothing named one. A mode the open app does not
/// declare is ignored by the reader (`ShellState::apply_boot_mode`), never a boot failure.
pub fn boot_app_mode() -> Option<String> {
    boot_axis(|descriptor| &descriptor.app_mode)
}

/// 📚️ The boot-requested example id, or `None`. It already collapses `?example=`/`--example` over the
/// `SEMIO_DEFAULT_EXAMPLE` seed the way React collapses the query over `VITE_SEMIO_DEFAULT_EXAMPLE`
/// into ONE `defaults.exampleId`. An id the open DIALECT does not author is ignored by the reader
/// (`shell::resolve_boot_example_id`), never a boot failure.
pub fn boot_app_example() -> Option<String> {
    boot_axis(|descriptor| &descriptor.app_example)
}

/// 🏷️ The boot brand id, or `None` — React's `brand`, resolved there by `resolveShellBrandById`.
pub fn boot_brand_id() -> Option<String> {
    boot_axis(|descriptor| &descriptor.brand_id)
}

/// 🏷️ The resolved brand ROW — React's `resolveShellBrandById(brandId)` answer. An UNBRANDED boot
/// answers `WgpuBootBrand::default()`, whose predicates read exactly as React's do for `undefined`
/// (`shouldReplayIntroductionOnLoad(undefined) === false`), so no caller needs an `Option` arm.
pub fn boot_brand() -> WgpuBootBrand {
    BOOT_DESCRIPTOR.with(|cell| cell.borrow().brand.clone())
}

/// 🏷️ The shell window's title — React's `ShellBrand.windowTitle`, `"Semio"` when this boot resolved no brand — which the
/// native window shows and its platform accessibility root announces.
pub fn boot_window_title() -> String {
    let title = boot_brand().window_title;
    if title.is_empty() {
        "Semio".to_string()
    } else {
        title
    }
}

/// #️⃣ The one-shot `#semio-broker=` proof the page carried, or `None`. React reads the same hash at
/// `🏛️ShellHost/🟦️.tsx:209` and hands it to its browser broker client.
pub fn boot_broker_proof() -> Option<String> {
    boot_axis(|descriptor| &descriptor.broker_proof)
}

/// 🔒️ The boot preference locks — read by the shell's `env_lock`, so a browser build locks exactly as
/// a native `SEMIO_LOCKED_*` deployment does instead of being unlockable for want of a process env.
pub fn boot_locks() -> WgpuBootLocks {
    BOOT_DESCRIPTOR.with(|cell| cell.borrow().locks.clone())
}

/// 👁️✏️ The boot-resolved role, contract freeze §5 — `"viewer"`/`"editor"`, anything else is
/// `ChromeRole::from_boot_env`'s own `editor` fallback.
pub fn boot_app_role() -> ui_wgpu::wgpu::component::role_chrome::ChromeRole {
    BOOT_DESCRIPTOR.with(|cell| ui_wgpu::wgpu::component::role_chrome::ChromeRole::from_boot_env(Some(cell.borrow().app_role.as_str())))
}
//#endregion 🧭️BootDescriptor

