/// 🖼️ Bounded identity and lease metadata; dropping it releases one token while the pool retains pixel storage.
#[derive(Debug)]
struct WorldSceneRaster {
    identity: SceneRasterIdentity,
    pending: Mutex<Option<SceneRasterLease>>,
}

