/// 🎥️ `World3dScene.camera_json` — the window's own camera measure, authored host-side.
#[derive(Clone, Debug, Default, Deserialize)]
#[serde(rename_all = "camelCase")]
struct World3dSceneCameraRecord {
    #[serde(default)]
