    }
    assert!(interrupted.terminal_is_empty());
    assert!(WorldTerrainMeshCursor::new("surface", (0, 0, 0), TerrainTileMeshPayload { positions: vec![0.0, 1.0], normals: Vec::new(), indices: vec![0, 1, 2], uvs: Vec::new() }, 80, 1, 1).is_err());
}

